"use client"

import { useState } from "react"
import { XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from "recharts"
import { Calendar, AlertCircle, CheckCircle2 } from "lucide-react"

const mockPredictionData = [
  { hour: "00:00", predicted: 4100 },
  { hour: "04:00", predicted: 3900 },
  { hour: "08:00", predicted: 6400 },
  { hour: "12:00", predicted: 7300 },
  { hour: "16:00", predicted: 7700 },
  { hour: "20:00", predicted: 8100 },
  { hour: "24:00", predicted: 5300 },
]

const states = [
  "Andhra Pradesh",
  "Arunachal Pradesh",
  "Assam",
  "Bihar",
  "Chhattisgarh",
  "Goa",
  "Gujarat",
  "Haryana",
  "Himachal Pradesh",
  "Jharkhand",
  "Karnataka",
  "Kerala",
  "Madhya Pradesh",
  "Maharashtra",
  "Manipur",
  "Meghalaya",
  "Mizoram",
  "Nagaland",
  "Odisha",
  "Punjab",
  "Rajasthan",
  "Sikkim",
  "Tamil Nadu",
  "Telangana",
  "Tripura",
  "Uttar Pradesh",
  "Uttarakhand",
  "West Bengal",
]

export default function PredictionForm() {
  const [formData, setFormData] = useState({
    state: "Maharashtra",
    date: new Date().toISOString().split("T")[0],
    temperature: 32,
    humidity: 65,
    rainfall: 0,
  })

  const [prediction, setPrediction] = useState(null)
  const [loading, setLoading] = useState(false)

  const handleInputChange = (e) => {
    const { name, value } = e.target
    setFormData({
      ...formData,
      [name]:
        name === "temperature" || name === "humidity" || name === "rainfall" ? Number.parseFloat(value) : value,
    })
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setLoading(true)

    setTimeout(() => {
      setPrediction({
        predictedDemand: 7850,
        confidence: 94.2,
        minDemand: 7200,
        maxDemand: 8500,
        trend: "increasing",
        recommendation: "High demand expected. Consider activating reserve capacity.",
      })
      setLoading(false)
    }, 1500)
  }

  return (
    <div className="p-6 space-y-8">
      <div>
        <h1 className="text-4xl font-bold text-white mb-2">Demand Prediction</h1>
        <p className="text-blue-200">Input parameters to forecast electricity demand</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1">
          <form
            onSubmit={handleSubmit}
            className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-6 space-y-4"
          >
            <h2 className="text-white font-semibold mb-4">Prediction Parameters</h2>
            <div>
              <label className="block text-blue-200 text-sm font-medium mb-2">State</label>
              <select
                name="state"
                value={formData.state}
                onChange={handleInputChange}
                className="w-full bg-blue-600 bg-opacity-20 border border-blue-400 border-opacity-30 text-white rounded-lg px-3 py-2 text-sm hover:bg-opacity-30 transition focus:outline-none focus:ring-2 focus:ring-blue-400"
              >
                {states.map((s) => (
                  <option key={s} value={s} className="bg-slate-900">
                    {s}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-blue-200 text-sm font-medium mb-2 flex items-center gap-2">
                <Calendar className="w-4 h-4" /> Date
              </label>
              <input
                type="date"
                name="date"
                value={formData.date}
                onChange={handleInputChange}
                className="w-full bg-blue-600 bg-opacity-20 border border-blue-400 border-opacity-30 text-white rounded-lg px-3 py-2 text-sm hover:bg-opacity-30 transition focus:outline-none focus:ring-2 focus:ring-blue-400"
              />
            </div>

            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-blue-200 text-sm font-medium">Temperature (°C)</label>
                <span className="text-orange-400 font-semibold">{formData.temperature}°</span>
              </div>
              <input
                type="range"
                name="temperature"
                min="10"
                max="50"
                value={formData.temperature}
                onChange={handleInputChange}
                className="w-full"
              />
            </div>

            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-blue-200 text-sm font-medium">Humidity (%)</label>
                <span className="text-blue-400 font-semibold">{formData.humidity}%</span>
              </div>
              <input
                type="range"
                name="humidity"
                min="20"
                max="100"
                value={formData.humidity}
                onChange={handleInputChange}
                className="w-full"
              />
            </div>

            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-blue-200 text-sm font-medium">Rainfall (mm)</label>
                <span className="text-cyan-400 font-semibold">{formData.rainfall}mm</span>
              </div>
              <input
                type="range"
                name="rainfall"
                min="0"
                max="100"
                value={formData.rainfall}
                onChange={handleInputChange}
                className="w-full"
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-slate-600 text-white font-semibold py-2 px-4 rounded-lg transition mt-6"
            >
              {loading ? "Predicting..." : "Get Prediction"}
            </button>
          </form>
        </div>

        <div className="lg:col-span-2 space-y-6">
          {prediction ? (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-4">
                  <p className="text-blue-200 text-sm mb-1">Predicted Demand</p>
                  <p className="text-white text-3xl font-bold">{prediction.predictedDemand} MW</p>
                  <p className="text-green-400 text-sm mt-2 flex items-center gap-1">
                    <CheckCircle2 className="w-4 h-4" />
                    {prediction.confidence}% Confidence
                  </p>
                </div>

                <div className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-4">
                  <p className="text-blue-200 text-sm mb-1">Expected Range</p>
                  <p className="text-white text-lg font-semibold">
                    {prediction.minDemand} - {prediction.maxDemand} MW
                  </p>
                  <p className="text-orange-400 text-sm mt-2">
                    ±{Math.round((prediction.maxDemand - prediction.minDemand) / 2)} MW
                  </p>
                </div>
              </div>

              <div className="bg-amber-600 bg-opacity-20 border border-amber-400 border-opacity-30 rounded-lg p-4 flex gap-3">
                <AlertCircle className="w-5 h-5 text-amber-400 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-amber-200 font-semibold text-sm">Recommendation</p>
                  <p className="text-amber-100 text-sm mt-1">{prediction.recommendation}</p>
                </div>
              </div>

              <div className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-6">
                <h3 className="text-white font-semibold mb-4">24-Hour Prediction</h3>
                <ResponsiveContainer width="100%" height={300}>
                  <AreaChart data={mockPredictionData}>
                    <defs>
                      <linearGradient id="colorPrediction" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8} />
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
                    <XAxis dataKey="hour" stroke="rgba(255,255,255,0.5)" />
                    <YAxis stroke="rgba(255,255,255,0.5)" />
                    <Tooltip
                      contentStyle={{
                        backgroundColor: "rgba(15, 23, 42, 0.95)",
                        border: "1px solid rgba(59, 130, 246, 0.5)",
                      }}
                    />
                    <Area
                      type="monotone"
                      dataKey="predicted"
                      stroke="#3b82f6"
                      fillOpacity={1}
                      fill="url(#colorPrediction)"
                      name="Predicted Demand"
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </>
          ) : (
            <div className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-12 flex items-center justify-center">
              <div className="text-center">
                <p className="text-blue-300 text-lg font-medium">Fill the form and click "Get Prediction"</p>
                <p className="text-blue-200 text-sm mt-2">
                  Our ML model will forecast electricity demand based on your parameters
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
